/* eslint-disable security/detect-non-literal-fs-filename -- Temporary paths are generated by the test. */
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { promises as fs } from "node:fs";
import os from "node:os";
import path from "node:path";
import { syncGmail } from "@/src/ingest/gmail";
import { UnrecognizedNoticeError } from "@/src/ingest/itau-parser";

let dir: string;
const raw = Buffer.from("From: aviso@itau.com.uy\r\nSubject: Aviso de transferencia realizada\r\nMessage-ID: <test@example.com>\r\n\r\ntest").toString("base64url");
const candidate = { labelIds: ["INBOX"], payload: { headers: [{ name: "From", value: "aviso@itau.com.uy" }, { name: "Subject", value: "Aviso de transferencia realizada" }] } };
beforeEach(async () => { dir = await fs.mkdtemp(path.join(os.tmpdir(), "budgetspin-gmail-")); await fs.writeFile(path.join(dir, "token"), JSON.stringify({ clientId: "test", clientSecret: "test", refreshToken: "test" }), { mode: 0o600 }); });
afterEach(async () => { await fs.rm(dir, { recursive: true, force: true }); });
function response(body: unknown, status = 200): Response { return Response.json(body, { status }); }

describe("Gmail sync", () => {
  it("checkpoints only after a page succeeds and retries it after failure", async () => {
    const calls: string[] = [];
    const fetcher: typeof fetch = async (url) => {
      const address = String(url); calls.push(address);
      if (address.includes("oauth2.googleapis")) return response({ access_token: "test" });
      if (address.endsWith("/profile")) return response({ emailAddress: "test@example.com", historyId: "123" });
      if (address.includes("format=metadata")) return response(candidate);
      if (address.includes("/messages/")) return response({ raw, sizeEstimate: 100, labelIds: ["INBOX"] });
      if (address.includes("/messages?")) return response({ messages: [{ id: "abc" }] });
      return response({ historyId: "124" });
    };
    const opts = { credentialsPath: path.join(dir, "token"), statePath: path.join(dir, "state"), fetcher };
    await expect(syncGmail({ ...opts, process: () => { throw new Error("failed"); } })).rejects.toThrow("failed");
    expect(JSON.parse(await fs.readFile(opts.statePath, "utf8")).mode).toBe("full");
    let count = 0;
    await syncGmail({ ...opts, process: () => { count++; } });
    expect(count).toBe(1);
    expect(JSON.parse(await fs.readFile(opts.statePath, "utf8"))).toMatchObject({ mode: "history", historyId: "124" });
    expect(calls.filter((call) => call.includes("/messages/abc") && call.includes("format=raw")).length).toBe(2);
  });

  it("does not download bodies of unrelated inbox messages", async () => {
    const calls: string[] = [];
    const fetcher: typeof fetch = async (url) => {
      const address = String(url); calls.push(address);
      if (address.includes("oauth2.googleapis")) return response({ access_token: "test" });
      if (address.endsWith("/profile")) return response({ emailAddress: "test@example.com", historyId: "123" });
      if (address.includes("/messages?")) return response({ messages: [{ id: "other" }, { id: "bank" }] });
      if (address.includes("/messages/other")) return response({ labelIds: ["INBOX"], payload: { headers: [{ name: "From", value: "person@example.com" }, { name: "Subject", value: "Personal" }] } });
      if (address.includes("format=metadata")) return response(candidate);
      if (address.includes("format=raw")) return response({ raw, sizeEstimate: 100, labelIds: ["INBOX"] });
      return response({ historyId: "124" });
    };
    let processed = 0;
    await syncGmail({ credentialsPath: path.join(dir, "token"), statePath: path.join(dir, "state"), fetcher, process: () => { processed++; } });
    expect(processed).toBe(1);
    expect(calls.some((call) => call.includes("/messages/other") && call.includes("format=raw"))).toBe(false);
    expect(calls.some((call) => call.includes("/messages/bank") && call.includes("format=raw"))).toBe(true);
  });

  it("retains unsupported notices while continuing and retries them on the next pass", async () => {
    let first = true;
    const seen: string[] = [];
    const fetcher: typeof fetch = async (url) => {
      const address = String(url);
      if (address.includes("oauth2.googleapis")) return response({ access_token: "test" });
      if (address.endsWith("/profile")) return response({ emailAddress: "test@example.com", historyId: "123" });
      if (address.includes("/messages?")) return response({ messages: [{ id: "bad" }, { id: "good" }] });
      if (address.includes("format=metadata")) return response(candidate);
      if (address.includes("format=raw")) {
        const id = address.includes("/bad?") ? "bad" : "good"; seen.push(id);
        return response({ raw: Buffer.from(`From: aviso@itau.com.uy\r\nSubject: Aviso de transferencia realizada\r\nMessage-ID: <${id}@example.com>\r\n\r\ntest`).toString("base64url"), sizeEstimate: 100, labelIds: ["INBOX"] });
      }
      return response({ historyId: "124" });
    };
    const opts = { credentialsPath: path.join(dir, "token"), statePath: path.join(dir, "state"), fetcher,
      process: (message: { messageId: string }) => { if (message.messageId.includes("bad") && first) throw new UnrecognizedNoticeError(); } };
    expect(await syncGmail(opts)).toEqual({ quarantined: 1 });
    expect(seen).toContain("good");
    expect(JSON.parse(await fs.readFile(opts.statePath, "utf8")).quarantined).toEqual(["bad"]);
    first = false;
    expect(await syncGmail(opts)).toEqual({ quarantined: 0 });
    expect(JSON.parse(await fs.readFile(opts.statePath, "utf8")).quarantined).toEqual([]);
  });

  it("normalizes line breaks without allowing header injection or blocking other messages", async () => {
    const fetcher: typeof fetch = async (url) => {
      const address = String(url);
      if (address.includes("oauth2.googleapis")) return response({ access_token: "test" });
      if (address.endsWith("/profile")) return response({ emailAddress: "test@example.com", historyId: "123" });
      if (address.includes("/messages?")) return response({ messages: [{ id: "malformed" }, { id: "folded" }] });
      if (address.includes("/messages/malformed") && address.includes("format=metadata")) return response({ labelIds: ["INBOX"], payload: { headers: [{ name: "Subject", value: "Bad\nHeader" }] } });
      if (address.includes("format=metadata")) return response({ labelIds: ["INBOX"], payload: { headers: [{ name: "From", value: "aviso@itau.com.uy" }, { name: "Subject", value: "Aviso de transferencia\r\n realizada" }] } });
      if (address.includes("format=raw")) return response({ raw, sizeEstimate: 100, labelIds: ["INBOX"] });
      return response({ historyId: "124" });
    };
    let count = 0;
    const statePath = path.join(dir, "state");
    expect(await syncGmail({ credentialsPath: path.join(dir, "token"), statePath, fetcher, process: () => { count++; } })).toEqual({ quarantined: 0 });
    expect(count).toBe(1);
    expect(JSON.parse(await fs.readFile(statePath, "utf8")).quarantined).toEqual([]);
  });

  it("reports only recognized provider failure reasons", async () => {
    const fetcher: typeof fetch = async (url) => {
      const address = String(url);
      if (address.includes("oauth2.googleapis")) return response({ access_token: "test" });
      if (address.endsWith("/profile")) return response({ emailAddress: "test@example.com", historyId: "123" });
      return response({ error: { errors: [{ reason: "userRateLimitExceeded", message: "private" }] } }, 403);
    };
    await expect(syncGmail({ credentialsPath: path.join(dir, "token"), statePath: path.join(dir, "state"), fetcher, process: () => {} }))
      .rejects.toThrow("Gmail request failed (403): userRateLimitExceeded.");
  });

  it("rejects non-private credential files", async () => {
    await fs.chmod(path.join(dir, "token"), 0o644);
    await expect(syncGmail({ credentialsPath: path.join(dir, "token"), statePath: path.join(dir, "state"), process: () => {} })).rejects.toThrow("private");
  });

  it("restarts full synchronization if history has expired", async () => {
    let historyCalls = 0;
    let fullCalls = 0;
    const fetcher: typeof fetch = async (url) => {
      const address = String(url);
      if (address.includes("oauth2.googleapis")) return response({ access_token: "test" });
      if (address.endsWith("/profile")) return response({ emailAddress: "test@example.com", historyId: "200" });
      if (address.includes("/messages?")) { fullCalls++; return response({}); }
      if (address.includes("/history?")) { historyCalls++; return historyCalls === 1 ? response({}, 404) : response({ historyId: "201" }); }
      throw new Error("Unexpected request.");
    };
    const statePath = path.join(dir, "state");
    const { createHash } = await import("node:crypto");
    const account = createHash("sha256").update("test@example.com").digest("hex");
    await fs.writeFile(statePath, JSON.stringify({ account, mode: "history", historyId: "123" }));
    await syncGmail({ credentialsPath: path.join(dir, "token"), statePath, fetcher, process: () => {} });
    expect(fullCalls).toBe(1);
    await syncGmail({ credentialsPath: path.join(dir, "token"), statePath, fetcher, process: () => {} });
    expect(JSON.parse(await fs.readFile(statePath, "utf8")).historyId).toBe("201");
  });
});
